19	func newPolicyCheckpointCmd() *cobra.Command {
20		var opts policyCheckpointOptions
21		cmd := &cobra.Command{
22			Use:   "checkpoint",
23			Short: "Inspect and update checkpoint policy",
24			Args:  cobra.NoArgs,
25			RunE: func(cmd *cobra.Command, _ []string) error {
26				return runPolicyCheckpoint(cmd, opts)
27			},
28		}
29	
30		cmd.Flags().StringVar(&opts.version, "checkpoint-version", "", "Set the checkpoint version written by this repository")
31		cmd.Flags().StringVar(&opts.minVersion, "checkpoint-min-version", "", "Set the minimum checkpoint version required by this repository")
32		cmd.Flags().BoolVar(&opts.force, "force", false, "Allow checkpoint policy version downgrades")
33		return cmd
34	}
