36	func runPolicyCheckpoint(cmd *cobra.Command, opts policyCheckpointOptions) error {
37		ctx := cmd.Context()
38		if err := ctx.Err(); err != nil {
39			return NewSilentError(err)
40		}
41		repo, err := gitrepo.OpenCurrent(ctx)
42		if err != nil {
43			return policyCheckpointError("open repository", err)
44		}
45		defer repo.Close()
46	
47		target, err := checkpointpolicy.ResolveTarget(ctx)
48		if err != nil {
49			return policyCheckpointError("resolve checkpoint policy remote", err)
50		}
51	
52		var state checkpointpolicy.State
53		if hasPolicyCheckpointUpdate(opts) {
54			state, err = checkpointpolicy.Update(ctx, repo, target, checkpointpolicy.UpdateOptions{
55				CheckpointVersion:    opts.version,
56				CheckpointMinVersion: opts.minVersion,
57				Force:                opts.force,
58			})
59			if err != nil {
60				return policyCheckpointError("update checkpoint policy", err)
61			}
62			if err := checkpointpolicy.Push(ctx, target); err != nil {
63				return policyCheckpointError("push checkpoint policy", err)
64			}
65			state.Source = checkpointpolicy.SourceRemote
66		} else {
67			state, err = checkpointpolicy.Sync(ctx, repo, target)
68			if err != nil {
69				return policyCheckpointError("sync checkpoint policy", err)
70			}
71		}
72	
73		fmt.Fprintf(cmd.OutOrStdout(), "checkpoint_version: %s\n", state.Policy.CheckpointVersion)
74		fmt.Fprintf(cmd.OutOrStdout(), "checkpoint_min_version: %s\n", state.Policy.CheckpointMinVersion)
75		fmt.Fprintf(cmd.OutOrStdout(), "source: %s\n", state.Source)
76		return nil
77	}
78	
79	func hasPolicyCheckpointUpdate(opts policyCheckpointOptions) bool {
80		return opts.version != "" || opts.minVersion != ""
81	}
82	
83	func policyCheckpointError(message string, err error) error {
84		wrapped := fmt.Errorf("%s: %w", message, err)
85		if errors.Is(wrapped, context.Canceled) {
86			return NewSilentError(wrapped)
87		}
88		return wrapped
89	}
